import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"Контроль доступа Bot","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/access.md","filePath":"ru/guides/access.md","lastUpdated":1792323081000}'),n={name:"ru/guides/access.md"};function s(l,t,d,g,i,h){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="контроль-доступа-bot" tabindex="-1">Контроль доступа Bot <a class="header-anchor" href="#контроль-доступа-bot" aria-label="Permalink to &quot;Контроль доступа Bot&quot;">​</a></h1><p>Контроль доступа в Memoh устроен в два слоя:</p><ul><li><strong>Channel Members</strong> (участники каналов) управляют идентичностями, приходящими из IM-каналов: Telegram, Discord, Feishu, QQ и подобных платформ.</li><li><strong>Workspace Members</strong> (участники рабочего пространства) управляют зарегистрированными пользователями Memoh в приложении и рабочем пространстве.</li></ul><p>Старая модель ACL-правил по-прежнему существует, но теперь это продвинутый движок, стоящий за доступом к чату в каналах. Повседневные изменения стоит начинать с вкладки <strong>Access</strong> Bot, через <strong>Channel Members</strong> и <strong>Workspace Members</strong>.</p><hr><h2 id="ментальная-модель" tabindex="-1">Ментальная модель <a class="header-anchor" href="#ментальная-модель" aria-label="Permalink to &quot;Ментальная модель&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Слой</th><th>Идентичность</th><th>Управляет</th></tr></thead><tbody><tr><td><strong>Channel Members</strong></td><td>Идентичность канала, наблюдаемая на IM-платформе</td><td>Может ли эта платформенная идентичность общаться с Bot и может ли она управлять Bot командами из IM</td></tr><tr><td><strong>Workspace Members</strong></td><td>Зарегистрированный аккаунт пользователя Memoh</td><td>Может ли этот пользователь работать с Bot в приложении, читать и записывать файлы, выполнять команды рабочего пространства, управлять настройками Bot</td></tr></tbody></table><p>Эти слои можно связать привязкой аккаунта. Пользователь рабочего пространства привязывает идентичность канала в <strong>Profile -&gt; Connected Accounts</strong>: генерирует одноразовый код и отправляет <code>/link &lt;code&gt;</code> любому Bot Memoh в IM. После привязки Memoh знает, что эта IM-идентичность принадлежит этому пользователю рабочего пространства.</p><p>Привязка сама по себе не даёт доступа. Она только связывает идентичности. Права по-прежнему берутся из Channel Members, Workspace Members, владения Bot или статуса системного администратора.</p><hr><h2 id="быстрыи-старт" tabindex="-1">Быстрый старт <a class="header-anchor" href="#быстрыи-старт" aria-label="Permalink to &quot;Быстрый старт&quot;">​</a></h2><h3 id="разрешить-чат-из-im-всем" tabindex="-1">Разрешить чат из IM всем <a class="header-anchor" href="#разрешить-чат-из-im-всем" aria-label="Permalink to &quot;Разрешить чат из IM всем&quot;">​</a></h3><ol><li>Откройте вкладку <strong>Access</strong> Bot.</li><li>Перейдите в <strong>Channel Members</strong>.</li><li>Установите <strong>Access Mode</strong> (режим доступа) в <strong>Blacklist Mode</strong> (режим чёрного списка).</li><li>Оставьте список участников пустым или добавьте только те идентичности, которые хотите заблокировать.</li></ol><p><strong>Blacklist Mode</strong> означает, что действие ACL по умолчанию — <code>allow</code>. Общаться могут все, пока не сработает запрещающее правило.</p><h3 id="разрешить-только-выбранные-im-идентичности" tabindex="-1">Разрешить только выбранные IM-идентичности <a class="header-anchor" href="#разрешить-только-выбранные-im-идентичности" aria-label="Permalink to &quot;Разрешить только выбранные IM-идентичности&quot;">​</a></h3><ol><li>Откройте <strong>Channel Members</strong>.</li><li>Установите <strong>Access Mode</strong> в <strong>Whitelist Mode</strong> (режим белого списка).</li><li>Добавьте идентичности каналов, которым доступ разрешён.</li><li>Держите флажок <strong>Chat</strong> включённым у каждой разрешённой идентичности.</li></ol><p><strong>Whitelist Mode</strong> означает, что действие ACL по умолчанию — <code>deny</code>. Общаться могут только те, на кого сработало разрешающее правило.</p><h3 id="дать-доступ-веб-пользователю" tabindex="-1">Дать доступ веб-пользователю <a class="header-anchor" href="#дать-доступ-веб-пользователю" aria-label="Permalink to &quot;Дать доступ веб-пользователю&quot;">​</a></h3><ol><li>Откройте <strong>Workspace Members</strong>.</li><li>Добавьте конкретного участника или добавьте <strong>Everyone</strong> (всех).</li><li>Выберите права, которые должен получить этот участник.</li></ol><p>Доступ к рабочему пространству — для зарегистрированных пользователей Memoh. Он не связан с доступом к чату из IM, пока пользователь не привяжет свою IM-идентичность.</p><hr><h2 id="channel-members" tabindex="-1">Channel Members <a class="header-anchor" href="#channel-members" aria-label="Permalink to &quot;Channel Members&quot;">​</a></h2><p><strong>Channel Members</strong> — поверхность управления доступом со стороны IM.</p><p>Каждая строка — это <strong>идентичность канала</strong> (один пользователь Telegram или участник Discord) либо <strong>группа</strong> (см. ниже). Участники добавляются из встроенного селектора в шапке карточки; кандидаты-идентичности и кандидаты-группы показываются в одном выпадающем списке, разделённые по секциям. У строки два независимых права:</p><table tabindex="0"><thead><tr><th>Право</th><th>Значение</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>Могут ли входящие IM-сообщения от этой идентичности запускать Bot.</td></tr><tr><td><strong>Manage</strong></td><td>Может ли эта идентичность управлять Bot через слэш-команды в IM. <strong>Manage</strong> не даёт <strong>Chat</strong> автоматически.</td></tr></tbody></table><h3 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h3><p>За флажком <strong>Chat</strong> стоят ACL-правила для <code>chat.trigger</code>.</p><p>В <strong>Blacklist Mode</strong>:</p><ul><li>по умолчанию — <code>allow</code></li><li>добавление идентичности или снятие флажка <strong>Chat</strong> создаёт запрещающее правило</li><li>установка флажка <strong>Chat</strong> удаляет запрещающее правило для этой идентичности</li></ul><p>В <strong>Whitelist Mode</strong>:</p><ul><li>по умолчанию — <code>deny</code></li><li>добавление идентичности или установка флажка <strong>Chat</strong> создаёт разрешающее правило</li><li>снятие флажка <strong>Chat</strong> удаляет разрешающее правило для этой идентичности</li></ul><h3 id="manage" tabindex="-1">Manage <a class="header-anchor" href="#manage" aria-label="Permalink to &quot;Manage&quot;">​</a></h3><p>Флажок <strong>Manage</strong> записывает локальное переопределение Channel Access для этой идентичности канала.</p><p><strong>Manage</strong> используется командами в IM. Оно позволяет идентичности канала действовать как управляющий Bot в слэш-командах уровня владельца. Оно намеренно независимо от <strong>Chat</strong>: управляющему всё равно могут быть запрещены обычные сообщения, если <strong>Chat</strong> выключен или ACL их отклоняет.</p><h3 id="группы-как-участники" tabindex="-1">Группы как участники <a class="header-anchor" href="#группы-как-участники" aria-label="Permalink to &quot;Группы как участники&quot;">​</a></h3><p>Помимо отдельных идентичностей, строкой участника можно добавить целый <strong>групповой чат</strong>. Кандидаты-группы берутся из разговоров, которые Bot наблюдал в своих каналах; такие строки помечены значком «Group».</p><ul><li>Флажок <strong>Chat</strong> у строки группы означает «все в этой группе»: в <strong>Whitelist Mode</strong> он разрешает всей группе запускать Bot, в <strong>Blacklist Mode</strong> — блокирует всю группу.</li><li><strong>Manage для групп недоступно.</strong> Управляющие — всегда отдельные идентичности каналов.</li><li>Комбинированные правила — «этот человек, в этой группе» — по-прежнему возможны через продвинутые ACL-правила.</li></ul><h3 id="платформенные-участники" tabindex="-1">Платформенные участники <a class="header-anchor" href="#платформенные-участники" aria-label="Permalink to &quot;Платформенные участники&quot;">​</a></h3><p>Если идентичность канала привязана к участнику рабочего пространства этого Bot, строка помечается как платформенный участник.</p><p>Когда у привязанного участника рабочего пространства есть <strong>Manage</strong> в <strong>Workspace Members</strong>, идентичность канала наследует <strong>Manage</strong> автоматически. Строка в Channel Members тогда показывает, что <strong>Manage</strong> унаследовано. Если вы переключите <strong>Manage</strong> в Channel Members, Memoh запишет локальное переопределение:</p><ul><li>локальное <strong>включено</strong> принудительно даёт этой идентичности канала <strong>Manage</strong></li><li>локальное <strong>выключено</strong> подавляет унаследованное <strong>Manage</strong> для этой идентичности канала</li><li><strong>Reset to inherited</strong> удаляет локальное переопределение и снова следует за Workspace Members</li></ul><p>Из Channel Members можно удалять только чисто локальные строки каналов. Строки платформенных участников происходят из привязки к рабочему пространству и управляются правами или отключением привязки.</p><hr><h2 id="workspace-members" tabindex="-1">Workspace Members <a class="header-anchor" href="#workspace-members" aria-label="Permalink to &quot;Workspace Members&quot;">​</a></h2><p><strong>Workspace Members</strong> — поверхность управления доступом со стороны веба и рабочего пространства.</p><p>Доступ можно выдать:</p><ul><li><strong>конкретному участнику</strong></li><li><strong>Everyone</strong> (всем)</li></ul><p>Владелец Bot показан как неявная запись владельца и всегда имеет полный доступ. Системные администраторы также получают полный доступ.</p><p>Права рабочего пространства:</p><table tabindex="0"><thead><tr><th>Право</th><th>Разрешает</th></tr></thead><tbody><tr><td><strong>Can chat</strong></td><td>Пользоваться Bot в веб-чатах.</td></tr><tr><td><strong>Read files</strong></td><td>Читать файлы рабочего пространства Bot.</td></tr><tr><td><strong>Write files</strong></td><td>Изменять файлы рабочего пространства Bot. Включает в себя <strong>Read files</strong>.</td></tr><tr><td><strong>Run commands</strong></td><td>Запускать выполнение команд в рабочем пространстве.</td></tr><tr><td><strong>Can manage</strong></td><td>Управлять настройками и доступом Bot. Включает в себя все остальные права рабочего пространства.</td></tr></tbody></table><p><strong>Can manage</strong> в рабочем пространстве перетекает и в Channel Members для привязанных идентичностей каналов. Если пользователь с правом управления в рабочем пространстве привяжет идентичность Telegram, эта идентичность Telegram унаследует <strong>Manage</strong> на стороне канала.</p><p><strong>Can chat</strong> в рабочем пространстве — это не то же самое, что <strong>Chat</strong> в канале. Права рабочего пространства авторизуют API приложения и рабочего пространства; <strong>Chat</strong> канала авторизует входящие IM-сообщения через движок ACL.</p><hr><h2 id="привязка-идентичностеи-каналов" tabindex="-1">Привязка идентичностей каналов <a class="header-anchor" href="#привязка-идентичностеи-каналов" aria-label="Permalink to &quot;Привязка идентичностей каналов&quot;">​</a></h2><p>Пользователи привязывают IM-идентичности в <strong>Profile -&gt; Connected Accounts</strong>:</p><ol><li>Нажмите <strong>Connect</strong>.</li><li>Скопируйте сгенерированную команду <code>/link &lt;code&gt;</code>.</li><li>Отправьте её любому Bot Memoh в IM-канале.</li><li>Код привяжет идентичность канала отправителя к текущему аккаунту пользователя Memoh.</li></ol><p>Важные детали:</p><ul><li>коды привязки одноразовые и истекают через короткое время</li><li><code>/link &lt;code&gt;</code> разрешён, даже когда отправитель отклонён чат-ACL, — так пользователи могут выбраться из непривязанного состояния</li><li>привязка действует на уровне аккаунта: она глобально связывает пользователя рабочего пространства и идентичность канала</li><li>привязка сама по себе не даёт ни <strong>Chat</strong>, ни <strong>Manage</strong></li></ul><p>После привязки соответствующая строка в Channel Members может унаследовать право управления из рабочего пространства.</p><hr><h2 id="access-mode-и-продвинутые-acl-правила" tabindex="-1">Access Mode и продвинутые ACL-правила <a class="header-anchor" href="#access-mode-и-продвинутые-acl-правила" aria-label="Permalink to &quot;Access Mode и продвинутые ACL-правила&quot;">​</a></h2><p>Чат каналов использует движок ACL. Страница Access представляет его как <strong>Access Mode</strong> плюс необязательные продвинутые правила.</p><table tabindex="0"><thead><tr><th>Access Mode</th><th>Действие ACL по умолчанию</th><th>Правила, которые имеют значение</th></tr></thead><tbody><tr><td><strong>Blacklist Mode</strong></td><td><code>allow</code></td><td>правила <code>deny</code></td></tr><tr><td><strong>Whitelist Mode</strong></td><td><code>deny</code></td><td>правила <code>allow</code></td></tr></tbody></table><p>Режим по умолчанию переопределяют только правила с действием, противоположным текущему. Правило с тем же действием, что и у режима по умолчанию, результата не меняет.</p><p>Продвинутые правила могут быть нацелены на:</p><ul><li>всех пользователей</li><li>всех пользователей на платформе</li><li>одну идентичность канала</li><li>одну идентичность канала на платформе</li></ul><p>Продвинутые правила можно также ограничить по области:</p><ul><li>любой чат</li><li>личные разговоры</li><li>групповые разговоры</li><li>треды</li><li>конкретный ID разговора</li><li>конкретный ID треда</li></ul><p>Цель правила отвечает за фильтрацию по платформе. Область источника — за фильтрацию по разговору и треду.</p><p>В отличие от прежней документации по ACL, текущие версии не предоставляют ручного приоритета правил и перетаскивания для сортировки. Думайте в терминах «текущий режим по умолчанию плюс сработавшие правила противоположного действия».</p><hr><h2 id="пресеты-при-создании" tabindex="-1">Пресеты при создании <a class="header-anchor" href="#пресеты-при-создании" aria-label="Permalink to &quot;Пресеты при создании&quot;">​</a></h2><p>Пресет ACL при создании Bot инициализирует только поведение чата каналов. Позже его можно изменить из <strong>Channel Members</strong>.</p><table tabindex="0"><thead><tr><th>Пресет</th><th>Начальное поведение</th></tr></thead><tbody><tr><td><code>allow_all</code></td><td>Действие по умолчанию <code>allow</code>; без дополнительных правил</td></tr><tr><td><code>private_only</code></td><td>Действие по умолчанию <code>deny</code>; разрешены личные разговоры</td></tr><tr><td><code>group_only</code></td><td>Действие по умолчанию <code>deny</code>; разрешены групповые разговоры</td></tr><tr><td><code>group_and_thread_only</code></td><td>Действие по умолчанию <code>deny</code>; разрешены группы и треды</td></tr><tr><td><code>deny_all</code></td><td>Действие по умолчанию <code>deny</code>; без дополнительных разрешающих правил</td></tr></tbody></table><p>Пресеты не настраивают Workspace Members и не создают привязок аккаунтов.</p><hr><h2 id="примеры" tabindex="-1">Примеры <a class="header-anchor" href="#примеры" aria-label="Permalink to &quot;Примеры&quot;">​</a></h2><h3 id="публичныи-im-bot-с-парои-блокировок" tabindex="-1">Публичный IM-Bot с парой блокировок <a class="header-anchor" href="#публичныи-im-bot-с-парои-блокировок" aria-label="Permalink to &quot;Публичный IM-Bot с парой блокировок&quot;">​</a></h3><p>Используйте <strong>Blacklist Mode</strong> в Channel Members. Оставьте <strong>Chat</strong> включённым по умолчанию и добавьте блокируемые идентичности. Продвинутые правила нужны, только если требуется заблокировать целую платформу или контекст группы либо треда.</p><h3 id="приватныи-im-bot" tabindex="-1">Приватный IM-Bot <a class="header-anchor" href="#приватныи-im-bot" aria-label="Permalink to &quot;Приватный IM-Bot&quot;">​</a></h3><p>Используйте <strong>Whitelist Mode</strong> в Channel Members. Добавьте разрешённые идентичности каналов и держите <strong>Chat</strong> включённым. Если те же люди должны управлять Bot из IM, выдайте им ещё и <strong>Manage</strong>.</p><h3 id="командныи-веб-bot" tabindex="-1">Командный веб-Bot <a class="header-anchor" href="#командныи-веб-bot" aria-label="Permalink to &quot;Командный веб-Bot&quot;">​</a></h3><p>Используйте <strong>Workspace Members</strong>. Добавьте конкретных пользователей или <strong>Everyone</strong>, затем выберите <strong>Can chat</strong>, файловые права, выполнение команд и <strong>Can manage</strong> в соответствии с их ролью в вебе и рабочем пространстве.</p><h3 id="управляющии-рабочим-пространством-управляет-и-из-telegram" tabindex="-1">Управляющий рабочим пространством управляет и из Telegram <a class="header-anchor" href="#управляющии-рабочим-пространством-управляет-и-из-telegram" aria-label="Permalink to &quot;Управляющий рабочим пространством управляет и из Telegram&quot;">​</a></h3><p>Выдайте пользователю <strong>Can manage</strong> в Workspace Members. Попросите его привязать аккаунт Telegram через <code>/link &lt;code&gt;</code>. Его идентичность Telegram унаследует <strong>Manage</strong> в Channel Members. Если нужно отключить управление со стороны Telegram только для этой идентичности, выключите <strong>Manage</strong> в Channel Members — создастся локальное переопределение.</p><hr><h2 id="отладка" tabindex="-1">Отладка <a class="header-anchor" href="#отладка" aria-label="Permalink to &quot;Отладка&quot;">​</a></h2><p>Когда результат доступа удивляет, проверяйте по порядку:</p><ol><li><strong>Какой слой задействован?</strong> IM-сообщения идут через чат-ACL каналов. API приложения и рабочего пространства — через Workspace Members.</li><li><strong>Привязана ли идентичность?</strong> Connected Accounts определяет, может ли управление из рабочего пространства унаследоваться в Channel Members.</li><li><strong>Какой сейчас Access Mode у канала?</strong> <strong>Blacklist Mode</strong> по умолчанию разрешает; <strong>Whitelist Mode</strong> по умолчанию запрещает.</li><li><strong>Manage унаследовано или переопределено?</strong> Информационное окно в Channel Members показывает, следует ли <strong>Manage</strong> за Workspace Members или переопределено локально.</li><li><strong>Что показывает <code>/access</code>?</strong> В IM команда <code>/access</code> сообщает текущую идентичность, право записи и контекст чат-ACL отправителя.</li></ol><p>Помните, что <strong>Manage</strong> и <strong>Chat</strong> раздельны. <strong>Manage</strong> может разрешать IM-команды уровня владельца, но обычный входящий чат всё равно требует, чтобы <strong>Chat</strong> канала пропустил отправителя.</p>',90)])])}const p=e(n,[["render",s]]);export{b as __pageData,p as default};
